import { useState, useMemo } from 'react'

export function Search(props: { items: string[] }) {
  const [query, setQuery] = useState('')
  const matches = useMemo(
    () => props.items.filter((item) => item.includes(query)),
    [props.items, query],
  )

  return (
    <div className="search">
      <input value={query} onChange={(e) => setQuery(e.currentTarget.value)} />
      <p>{matches.length} matches</p>
      <ul>
        {matches.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </div>
  )
}

