import { For } from '@pyreon/core'
import { computed, signal } from '@pyreon/reactivity'

export function Search(props: { items: string[] }) {
  const query = signal('')
  const matches = computed(() =>
    props.items.filter((item) => item.includes(query())),
  )

  return (
    <div class="search">
      <input value={query()} onInput={(e) => query.set(e.currentTarget.value)} />
      <p>{matches().length} matches</p>
      <ul>
        <For each={matches} by={(item) => item}>
          {(item) => <li>{item}</li>}
        </For>
      </ul>
    </div>
  )
}

