// vite.config.ts
import pyreon from '@pyreon/vite-plugin'
import { defineConfig } from 'vite'

export default defineConfig({
  // replaces @vitejs/plugin-react: react, react-dom, react-dom/client
  // and the JSX runtime now resolve to @pyreon/react-compat
  plugins: [pyreon({ compat: 'react' })],
})

// theme.ts: a native Pyreon provider
import { createContext, nativeCompat, provide } from '@pyreon/core'
import type { VNodeChild } from '@pyreon/core'

export const Theme = createContext<'light' | 'dark'>('light')

// It calls provide(), so mark it: the React-compat JSX runtime
// then calls it as a Pyreon component instead of wrapping it.
export const ThemeProvider = nativeCompat(
  (props: { theme: 'light' | 'dark'; children?: VNodeChild }) => {
    provide(Theme, props.theme)
    return props.children
  },
)

// Badge.tsx: plain React code, reading the Pyreon context
import { useContext } from 'react'
import { Theme } from './theme'

export function Badge() {
  const theme = useContext(Theme)
  return <span className={`badge ${theme}`}>{theme}</span>
}

